local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/xHeptc/Kavo-UI-Library/main/source.lua"))()
local Window = Library.CreateLib("TITLE", "Midnight")
local Tab = Window:NewTab("Joe Goldberg")
    local Section = Tab:NewSection("Skill")
        Section:NewKeybind("Choke Slam", "KeybindInfo", Enum.KeyCode.Z, function()
            local args = {
    [1] = game:GetService("Players").LocalPlayer
}

game:GetService("ReplicatedStorage").Characters.Joe.Remotes.ChokeSlam:FireServer(unpack(args))            
    end)
    Section:NewKeybind("Bugs Slam", "KeybindInfo", Enum.KeyCode.X, function()
        local args = {
    [1] = game:GetService("Players").LocalPlayer
}

game:GetService("ReplicatedStorage").Characters.Joe.Remotes.BugsSlam:FireServer(unpack(args))        
    end)
    Section:NewKeybind("The Cage", "KeybindInfo", Enum.KeyCode.C, function()
        local args = {
            [1] = game:GetService("Players").LocalPlayer
        }

        game:GetService("ReplicatedStorage").Characters.Joe.Remotes.TheCage:FireServer()
    end)
    Section:NewKeybind("Finisher", "KeybindInfo", Enum.KeyCode.V, function()
        local args = {
            [1] = game:GetService("Players").LocalPlayer
        }

        game:GetService("ReplicatedStorage").Characters.Joe.Remotes.Finisher:FireServer()
    end)
    Section:NewKeybind("Counter", "KeybindInfo", Enum.KeyCode.T, function()
        local args = {
    [1] = game:GetService("Players").LocalPlayer
}

game:GetService("Players").LocalPlayer.Character.Joe.CounterActivate:FireServer(unpack(args))                
    end)
local Tab = Window:NewTab("Cradit")
    local Section = Tab:NewSection("UI")
    Section:NewKeybind("Hide UI", "KeybindInfo", Enum.KeyCode.P, function()
 Library:ToggleUI()
end)

local OrionLib = loadstring(game:HttpGet(('https://raw.githubusercontent.com/shlexware/Orion/main/source')))()
local Window = OrionLib:MakeWindow({Name = "M(orbius)arvellous", HidePremium = false, SaveConfig = true, ConfigFolder = "OrionTest"})
local Tab = Window:MakeTab({
Name = "Characters",
Icon = "rbxassetid://460729824",
PremiumOnly = false
})

local function changeplayer(char)
game:GetService("ReplicatedStorage").SelectCharacter.ChangeChar:FireServer(char)
end

Tab:AddButton({
Name = "Thanos",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").SelectCharacter.Thanos)
  end    
})

Tab:AddButton({
Name = "Chad",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").SelectCharacter.GigaChad)
  end    
})

Tab:AddButton({
Name = "Wanda",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").SelectCharacter.Wanda)
  end    
})

Tab:AddButton({
Name = "Chadette",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").Skins.GigaChad.Skin1)
  end    
})

Tab:AddButton({
Name = "Saitama",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").Skins.GigaChad.Skin2)
  end    
})

Tab:AddButton({
Name = '"Empty"',
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").SelectCharacter.Empty)
  end    
})

Tab:AddButton({
Name = "Vecna (functions like Eleven but worse)",
Callback = function()
      changeplayer(game:GetService("ReplicatedStorage").SelectCharacter.Vecna)
  end    
})

Tab:AddButton({
Name = '"Fake" (A sort of ghost / spectator mode)',
Callback = function()
